// Package sqlite is the catalogue on the platform database (queries.sql, generated by sqlc).
package sqlite

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"time"

	"github.com/IhebBelhadj/opsforge-academy/academy/internal/catalog"
	"github.com/IhebBelhadj/opsforge-academy/academy/internal/platform/sqlite"
)

// Repo stores catalogue entries; it is contentimport's Store and the catalogue's Reader.
type Repo struct {
	db *sql.DB
	q  *Queries
}

// NewRepo uses the open database db.
func NewRepo(db *sql.DB) *Repo { return &Repo{db: db, q: New(db)} }

// Entries returns every entry, retired ones included.
func (r *Repo) Entries(ctx context.Context) ([]catalog.Entry, error) {
	rows, err := r.q.AllContent(ctx)
	if err != nil {
		return nil, err
	}
	out := make([]catalog.Entry, len(rows))
	for i, row := range rows {
		out[i] = toEntry(row)
	}
	return out, nil
}

// Live returns one entry unless it is retired (catalog.ErrNotFound).
func (r *Repo) Live(ctx context.Context, kind catalog.Kind, key string) (catalog.Entry, error) {
	row, err := r.q.LiveContent(ctx, LiveContentParams{Kind: string(kind), Key: key})
	if errors.Is(err, sql.ErrNoRows) {
		return catalog.Entry{}, catalog.ErrNotFound
	}
	if err != nil {
		return catalog.Entry{}, err
	}
	return toEntry(AllContentRow(row)), nil
}

// LiveList returns the entries of a kind that are not retired, by pack then position.
func (r *Repo) LiveList(ctx context.Context, kind catalog.Kind) ([]catalog.Entry, error) {
	rows, err := r.q.LiveContentOfKind(ctx, string(kind))
	if err != nil {
		return nil, err
	}
	out := make([]catalog.Entry, len(rows))
	for i, row := range rows {
		out[i] = toEntry(AllContentRow(row))
	}
	return out, nil
}

// List returns every entry of a kind, retired ones included, by pack then position.
func (r *Repo) List(ctx context.Context, kind catalog.Kind) ([]catalog.Entry, error) {
	rows, err := r.q.ContentOfKind(ctx, string(kind))
	if err != nil {
		return nil, err
	}
	out := make([]catalog.Entry, len(rows))
	for i, row := range rows {
		out[i] = toEntry(AllContentRow(row))
	}
	return out, nil
}

func toEntry(row AllContentRow) catalog.Entry {
	return catalog.Entry{
		Kind: catalog.Kind(row.Kind), Key: row.Key, PackID: row.PackID, CourseID: row.CourseID.String,
		Position: int(row.Position), Title: row.Title, Hash: row.ContentHash, Doc: json.RawMessage(row.Doc),
		Retired: row.Retired == 1,
	}
}

// Apply writes upsert (un-retiring them) and retires retire, at `at`, in one transaction.
func (r *Repo) Apply(ctx context.Context, upsert, retire []catalog.Entry, at time.Time) error {
	tx, err := r.db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback() }() // a no-op after Commit
	q, stamp := r.q.WithTx(tx), sqlite.FormatTime(at)
	for _, e := range upsert {
		if err := q.UpsertContent(ctx, UpsertContentParams{
			Kind: string(e.Kind), Key: e.Key, PackID: e.PackID,
			CourseID: sql.NullString{String: e.CourseID, Valid: e.CourseID != ""}, Position: int64(e.Position),
			Title: e.Title, ContentHash: e.Hash, Doc: string(e.Doc), UpdatedAt: stamp,
		}); err != nil {
			return fmt.Errorf("%s %s: %w", e.Kind, e.Key, err)
		}
	}
	for _, e := range retire {
		if err := q.RetireContent(ctx, RetireContentParams{UpdatedAt: stamp, Kind: string(e.Kind), Key: e.Key}); err != nil {
			return fmt.Errorf("retire %s %s: %w", e.Kind, e.Key, err)
		}
	}
	return tx.Commit()
}

// UpdatedAt is when the entry last changed (for a pack: when it was last imported with changes).
func (r *Repo) UpdatedAt(ctx context.Context, kind catalog.Kind, key string) (time.Time, error) {
	s, err := r.q.ContentUpdatedAt(ctx, ContentUpdatedAtParams{Kind: string(kind), Key: key})
	if err != nil {
		return time.Time{}, err
	}
	return sqlite.ParseTime(s)
}
